'use client';

import type { Easing, Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface Scissor01IconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface Scissor01IconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const SNIP_DURATION = 0.95;
const SNIP_TIMES = [0, 0.16, 0.32, 0.5, 0.66, 1];
const SNIP_EASE: Easing[] = [
  [0.33, 1, 0.68, 1],
  [0.55, 0, 0.85, 0.35],
  'easeInOut',
  [0.55, 0, 0.85, 0.35],
  'easeInOut',
];
const PIVOT = { transformBox: 'view-box', originX: 10.6 / 24, originY: 0.5 } as const;

// rest-parity: split-source-path
// Two snips: each blade turns on the shared pivot, opens a little wider, then
// snaps nearly shut, and the scissors creep forward with each cut. The rings
// stop short of touching. The frame stays still.
const scissorVariants: Variants = {
  normal: { translateX: 0 },
  animate: {
    translateX: [0, 0, -0.6, -0.6, -1.2, 0],
    transition: { duration: SNIP_DURATION, times: SNIP_TIMES, ease: SNIP_EASE },
  },
};

const bladeVariants: Variants = {
  normal: { rotate: 0 },
  animate: (direction: number) => ({
    rotate: [0, 7, -16, 5, -16, 0].map((angle) => angle * direction),
    transition: { duration: SNIP_DURATION, times: SNIP_TIMES, ease: SNIP_EASE },
  }),
};

const Scissor01Icon = forwardRef<Scissor01IconHandle, Scissor01IconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: false,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <path
            d="M2.5 12C2.5 7.52166 2.5 5.28249 3.89124 3.89124C5.28249 2.5 7.52166 2.5 12 2.5C16.4783 2.5 18.7175 2.5 20.1088 3.89124C21.5 5.28249 21.5 7.52166 21.5 12C21.5 16.4783 21.5 18.7175 20.1088 20.1088C18.7175 21.5 16.4783 21.5 12 21.5C7.52166 21.5 5.28249 21.5 3.89124 20.1088C2.5 18.7175 2.5 16.4783 2.5 12Z"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <motion.g variants={scissorVariants} animate={controls} initial="normal">
            <motion.path
              d="M10.6 12L13.4949 14.3865M10.6 12L7 9M16 15.5C16 16.3284 15.3284 17 14.5 17C13.6716 17 13 16.3284 13 15.5C13 14.6716 13.6716 14 14.5 14C15.3284 14 16 14.6716 16 15.5Z"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={bladeVariants}
              custom={1}
              animate={controls}
              initial="normal"
              style={PIVOT}
            />
            <motion.path
              d="M13.4368 9.55807L10.6 12M10.6 12L7 15M16 8.5C16 9.32843 15.3284 10 14.5 10C13.6716 10 13 9.32843 13 8.5C13 7.67157 13.6716 7 14.5 7C15.3284 7 16 7.67157 16 8.5Z"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={bladeVariants}
              custom={-1}
              animate={controls}
              initial="normal"
              style={PIVOT}
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);

Scissor01Icon.displayName = 'Scissor01Icon';

export { Scissor01Icon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { spring, useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

/**
 * A damped spring as the easing of one keyframe segment: the value overshoots
 * its target and settles on it. Use it for landings so every icon shares the
 * same physical bounce. Higher `bounce` gives more oscillation.
 */
export function springEase(bounce = 0.45, visualDuration = 0.35) {
  const generator = spring({ keyframes: [0, 1], bounce, visualDuration });
  let settle = 0;
  while (!generator.next(settle).done && settle < 5000) settle += 10;
  return (progress: number) =>
    progress >= 1 ? 1 : generator.next(progress * settle).value;
}

/**
 * One wave of a looping wave train, like sound leaving a speaker. The wave
 * fades in at the first pose, moves through each pose at an even pace, fades
 * out at the last, and returns hidden to the first. Give each wave the pose it
 * rests on; waves on neighbouring poses then move as one train. All poses must
 * share the same path commands.
 */
export function waveTrain(poses: string[], rest: number, duration: number) {
  const last = poses.length - 1;
  const steps = [];
  for (let pose = rest; pose <= last; pose++) steps.push(pose);
  for (let pose = 0; rest > 0 && pose <= rest; pose++) steps.push(pose);
  return {
    d: steps.map((pose) => poses[pose]),
    opacity: steps.map((pose) => (pose === 0 || pose === last ? 0 : 1)),
    transition: {
      duration,
      ease: 'linear' as const,
      // The return from the last pose to the first is a hidden jump.
      times: steps.map((_, k) => {
        if (k <= last - rest) return k / last;
        return (k - 1) / last + (k === last - rest + 1 ? 0.001 : 0);
      }),
      repeat: Infinity,
    },
  };
}

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
